if (charging=1 and front MCU high-voltage detection flag=0) then (yes)
  :transition to state 153;
else (no)
  if (BMS-fast charger handshake flag=0 and front MCU high-voltage flag=0) then (yes)
    :enter state 155;
    if (pre-charge failure occurs) then (yes)
      :move to state 175;
      if (fast charging inactive) then (yes)
        :shut down;
        end
      else (no)
      endif
    elseif (high-voltage shutdown request detected (value=2)) then (yes)
      :wait 0.8 seconds;
      :enter state 175;
      if (fast charging inactive) then (yes)
        :shut down;
        end
      else (no)
      endif
    elseif (ignition switch status=2) then (yes)
      :remain in state 155;
      if (high-voltage shutdown request (value=2) exists) then (yes)
        :pause for 0.8 seconds;
      else (no)
      endif
      if (ignition switch reads 0) then (yes)
        :proceed to state 175;
      else (no)
      endif
      if (fast charging inactive) then (yes)
        :shut down;
        end
      else (no)
      endif
    elseif (fast charging inactive) then (yes)
      :switch to state 175;
      :shut down;
      end
    else (no)
    endif
  else (no)
  endif
endif
@enduml

